public final class NodeCloudAudit {
 private static void check(String n,boolean ok,Object detail){ServerAudit.check("node/cloud: "+n,ok,detail);}
 private static ItemStack item(String id){return EMTRecipes.stack(id);}
 private static ItemStack charged(String id,double eu){var s=item(id);ElectricItem.manager.charge(s,eu,10,true,false);return s;}
 private static PlayerInteractEvent.RightClickBlock click(net.minecraft.world.entity.player.Player p,BlockPos pos,boolean canceled){var hit=new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false);var event=new PlayerInteractEvent.RightClickBlock(p,InteractionHand.MAIN_HAND,pos,hit);event.setCanceled(canceled);NeoForge.EVENT_BUS.post(event);return event;}
 public static void run(ServerLevel l,BlockPos base){var p=FakePlayerFactory.getMinecraft(l);p.setGameMode(GameType.SURVIVAL);p.getAbilities().invulnerable=false;p.setShiftKeyDown(false);p.getInventory().clearContent();for(var slot:EquipmentSlot.values())p.setItemSlot(slot,ItemStack.EMPTY);p.removeAllEffects();
  var at=base.offset(8,5,52);l.setBlock(at.below(),Blocks.STONE.defaultBlockState(),3);l.setBlock(at,Blocks.AIR.defaultBlockState(),3);p.setPos(at.getX()+.5,at.getY(),at.getZ()-2);var stack=item("emt:portable_node");p.setItemInHand(InteractionHand.MAIN_HAND,stack);var result=stack.useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at.below()).add(0,.5,0),Direction.UP,at.below(),false)));var node=l.getBlockEntity(at);check("real block-item placement generates a native portable node",result.consumesAction()&&node instanceof TilePortableNode&&stack.isEmpty(),node);if(!(node instanceof TilePortableNode portable))return;check("native biome/environment generator fills real node aspects",portable.reservoir.aspectsBase.visSize()>0&&portable.reservoir.aspects.visSize()>0,portable.reservoir.aspectsBase);check("portable node is always fading and unstable",portable.nodeType==NodeType.UNSTABLE&&portable.reservoir.modifier==NodeModifier.FADING,"nature");
  var state=l.getBlockState(at);check("portable node has native8light/unbreakable/no collision",state.getLightEmission(l,at)==8&&state.getDestroySpeed(l,at)<0&&state.getCollisionShape(l,at).isEmpty(),"properties");check("portable node has no mining/silk drops and rejects entities",Block.getDrops(state,l,at,portable,p,new ItemStack(Items.DIAMOND_PICKAXE)).isEmpty()&&!state.getBlock().canEntityDestroy(state,l,at,p),"protected");l.explode(null,at.getX()+.5,at.getY()+.5,at.getZ()+.5,2,Level.ExplosionInteraction.BLOCK);check("portable node survives actual explosion",l.getBlockState(at).is(EMTBlocks.PORTABLE_NODE.get()),"blast");
  var saved=portable.saveWithFullMetadata(l.registryAccess());var loaded=BlockEntity.loadStatic(at,state,saved,l.registryAccess());check("registered addon node type and aspects survive real block entity reload",loaded instanceof TilePortableNode&&loaded.getType()==EMTBlocks.PORTABLE_NODE_ENTITY.get()&&((TilePortableNode)loaded).reservoir.aspectsBase.visSize()==portable.reservoir.aspectsBase.visSize(),saved.getString("id"));portable.nodeType=NodeType.NORMAL;portable.reservoir.modifier=NodeModifier.BRIGHT;TilePortableNode.tick(l,at,state,portable);check("native stabilizer/effect mutations cannot normalize portable nature",portable.nodeType==NodeType.UNSTABLE&&portable.reservoir.modifier==NodeModifier.FADING,"forced nature");
  var wand=item("tc4modern:wand");p.setItemInHand(InteractionHand.MAIN_HAND,wand);p.setPos(at.getX()+.5,at.getY()+.5-p.getEyeHeight(),at.getZ()-3);p.setYRot(0);p.setXRot(0);wand.use(l,p,InteractionHand.MAIN_HAND);wand.getItem().onUseTick(l,p,wand,72000);check("real native wand drains portable node vis",p.isUsingItem()&&Aspect.getPrimalAspects().stream().anyMatch(a->WandData.get(wand,a)>0),Aspect.getPrimalAspects().stream().map(a->a.getTag()+"="+WandData.get(wand,a)).toList());p.stopUsingItem();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STONE));p.setShiftKeyDown(true);state.useWithoutItem(l,p,new BlockHitResult(Vec3.atCenterOf(at),Direction.NORTH,at,false));check("holding an item prevents accidental node disposal",l.getBlockState(at).is(EMTBlocks.PORTABLE_NODE.get()),"held item");p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);state.useWithoutItem(l,p,new BlockHitResult(Vec3.atCenterOf(at),Direction.NORTH,at,false));check("native shift-empty-hand interaction disposes node without drops",l.isEmptyBlock(at)&&l.getEntitiesOfClass(ItemEntity.class,new AABB(at)).isEmpty(),"disposed");p.setShiftKeyDown(false);
  var cloudPos=base.offset(12,5,52);p.setPos(cloudPos.getX()+.5,cloudPos.getY(),cloudPos.getZ()-2);l.setBlock(cloudPos,TC4Modern.NITOR_BLOCK.get().defaultBlockState(),3);var weak=charged("ic2:re_battery",1000);p.setItemInHand(InteractionHand.MAIN_HAND,weak);click(p,cloudPos,false);check("low-transfer battery cannot electrify nitor or lose partial EU",l.getBlockState(cloudPos).is(TC4Modern.NITOR_BLOCK.get())&&ElectricItem.manager.getCharge(weak)==1000,"transfer100");var shortCharge=charged("ic2:advanced_re_battery",255);p.setItemInHand(InteractionHand.MAIN_HAND,shortCharge);click(p,cloudPos,false);check("undercharged advanced battery loses no partial EU",l.getBlockState(cloudPos).is(TC4Modern.NITOR_BLOCK.get())&&ElectricItem.manager.getCharge(shortCharge)==255,"atomic");var tool=charged("emt:thaumium_drill",1000);p.setItemInHand(InteractionHand.MAIN_HAND,tool);click(p,cloudPos,false);check("non-provider electric tool cannot generate cloud",l.getBlockState(cloudPos).is(TC4Modern.NITOR_BLOCK.get())&&ElectricItem.manager.getCharge(tool)==1000,"external discharge");var battery=charged("ic2:advanced_re_battery",1000);p.setItemInHand(InteractionHand.MAIN_HAND,battery);click(p,cloudPos,true);check("canceled native interaction preserves nitor and battery",l.getBlockState(cloudPos).is(TC4Modern.NITOR_BLOCK.get())&&ElectricItem.manager.getCharge(battery)==1000,"protection");var event=click(p,cloudPos,false);check("native advanced battery interaction creates cloud for256EU",event.isCanceled()&&l.getBlockState(cloudPos).is(EMTBlocks.ELECTRIC_CLOUD.get())&&ElectricItem.manager.getCharge(battery)==744,ElectricItem.manager.getCharge(battery));var cloud=l.getBlockState(cloudPos);check("cloud retains light15/no collision/is not air",cloud.getLightEmission(l,cloudPos)==15&&cloud.getCollisionShape(l,cloudPos).isEmpty()&&!cloud.isAir()&&l.getBlockEntity(cloudPos) instanceof TileElectricCloud,"cloud properties");check("electric cloud drops its actual item",Block.getDrops(cloud,l,cloudPos,l.getBlockEntity(cloudPos),p,new ItemStack(Items.IRON_PICKAXE)).stream().anyMatch(s->s.is(EMTBlocks.ELECTRIC_CLOUD.get().asItem())),"drop");
  var worn=baubles.api.BaublesApi.getBaubles(p);worn.setItem(1,item("emt:one_ring"));p.getAbilities().invulnerable=false;var zombie=new Zombie(l);zombie.setTarget(p);check("native mob target event rejects One Ring wearer even during curse vulnerability",zombie.getTarget()==null,"pacified");worn.setItem(1,ItemStack.EMPTY);zombie.setTarget(p);check("removing One Ring restores normal mob targeting",zombie.getTarget()==p,"normal target");p.removeAllEffects();
  var creeper=new Creeper(EntityType.CREEPER,l);creeper.setPos(p.position());creeper.thunderHit(l,new LightningBolt(EntityType.LIGHTNING_BOLT,l));var drops=new ArrayList<ItemEntity>();NeoForge.EVENT_BUS.post(new LivingDropsEvent(creeper,creeper.damageSources().generic(),drops,true));check("charged creeper death drops original lightning summoner",drops.stream().anyMatch(d->d.getItem().is(EMTItems.material("lightning_summoner"))&&d.getItem().getCount()==1),"charged drop");var chicken=TaintedContent.TYPES.get("chicken").get().create(l);long seed=0;for(;seed<100;seed++){chicken.getRandom().setSeed(seed);if(chicken.getRandom().nextInt(3)==2)break;}chicken.getRandom().setSeed(seed);drops.clear();NeoForge.EVENT_BUS.post(new LivingDropsEvent(chicken,chicken.damageSources().generic(),drops,true));check("native tainted chicken drop event adds original0-2feathers",drops.stream().anyMatch(d->d.getItem().is(EMTItems.material("tainted_feather"))&&d.getItem().getCount()==2),"seed"+seed);
  check("portable node crucible and two cloud text pages registered",TC4Addons.crucibleRecipes().containsKey("emt:portableNode")&&thaumcraft.api.research.ResearchCategories.getResearch("Electric Cloud").getPages().length==2,"research/recipe");p.getInventory().clearContent();
 }
}
